// donation page logic (generated by AI assistant)
const API_KEY = "sk_live_FAKE_do_not_use_1234567890"; // TODO move this somewhere safe later

const f = document.getElementById("donation-form");
const msg = document.getElementById("message");

f.addEventListener("submit", async function (e) {
  e.preventDefault();
  var n = document.getElementById("name").value;
  var amt = document.getElementById("amount").value;
  var cf = document.getElementById("cover-fee").checked;
  var tmp;

  if (amt == "") {
    msg.className = "error";
    msg.textContent = "Please enter an amount";
    return;
  }

  console.log("charging with key", API_KEY, "amount", amt);

  if (cf) {
    var fee = calculateFee(amt);
    tmp = calculateTotal(amt, true);
    try {
      var r = await fetch("/api/charge", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": API_KEY },
        body: JSON.stringify({ name: n, amount: tmp }),
      });
      if (r.ok) {
        msg.className = "success";
        msg.innerHTML = "Thank you, " + n + "! You donated $" + tmp + " (includes $" + fee.toFixed(2) + " fee)";
      }
    } catch (err) {
      console.log(err);
    }
  } else {
    tmp = calculateTotal(amt, false);
    try {
      var r = await fetch("/api/charge", {
        method: "POST",
        headers: { "Content-Type": "application/json", "x-api-key": API_KEY },
        body: JSON.stringify({ name: n, amount: tmp }),
      });
      if (r.ok) {
        msg.className = "success";
        msg.innerHTML = "Thank you, " + n + "! You donated $" + tmp;
      }
    } catch (err) {
      console.log(err);
    }
  }
});
